def main():
    tok = AutoTokenizer.from_pretrained(MODEL, trust_remote_code=True)
    print("loading model (bf16 cpu)...", flush=True)
    t0 = time.time()
    model = AutoModelForSequenceClassification.from_pretrained(
        MODEL, trust_remote_code=True, dtype=torch.bfloat16, device_map="cpu",
        attn_implementation="eager")
    model.eval()
    print(f"loaded in {time.time()-t0:.0f}s", flush=True)

    out = []
    for i, (q, d) in enumerate(PAIRS):
        msgs = [{"role": "query", "content": [{"type": "text", "text": q}]},
                {"role": "document", "content": [{"type": "text", "text": d}]}]
        enc = tok.apply_chat_template(msgs, tokenize=True, add_generation_prompt=False,
                                      return_dict=True, return_tensors="pt")
        ids = enc["input_ids"]
        am = enc.get("attention_mask", torch.ones_like(ids))
        t1 = time.time()
        with torch.no_grad():
            logits = model(input_ids=ids, attention_mask=am).logits
        v = logits.squeeze().float().item()
        print(f"[{i}] S={ids.shape[1]} logit={v:+.6f} ({time.time()-t1:.0f}s)", flush=True)
        out.append({"query": q, "doc": d, "ids": ids[0].tolist(),
                    "attention_mask": am[0].tolist(), "logit": v})
    json.dump(out, open("/tmp/nemotron_ref.json", "w"))
    print("saved /tmp/nemotron_ref.json")

if __name__ == "__main__":
    main()
